package decide

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"testing"
)

// expectedTick is the dispatcher's own output for one recorded tick. The fixtures are
// generated by scripts/record-decide-ticks.py from ~/logs/fleet-autodispatch.log.
type expectedTick struct {
	Status     string            `json:"status"`
	Dispatches []int             `json:"dispatches"`
	Reasons    map[string]string `json:"reasons"`
}

// TestOracle replays every recorded tick through Decide and diffs the task set and
// the skip reasons against the Python dispatcher's output for the same inputs.
func TestOracle(t *testing.T) {
	paths, err := filepath.Glob("testdata/ticks/*/snapshot.json")
	if err != nil {
		t.Fatalf("glob: %v", err)
	}
	if len(paths) < 20 {
		t.Fatalf("oracle needs at least 20 recorded ticks, found %d", len(paths))
	}

	for _, path := range paths {
		path := path
		t.Run(filepath.Base(filepath.Dir(path)), func(t *testing.T) {
			snapshot := readJSON[Snapshot](t, path)
			expected := readJSON[expectedTick](t, filepath.Join(filepath.Dir(path), "expected.json"))

			result := Decide(snapshot)
			if string(result.Status) != expected.Status {
				t.Fatalf("status = %q, want %q", result.Status, expected.Status)
			}

			got := dispatchNumbers(result)
			sort.Ints(got)
			want := append([]int(nil), expected.Dispatches...)
			sort.Ints(want)
			if fmt.Sprint(got) != fmt.Sprint(want) {
				t.Fatalf("dispatches = %v, want %v", got, want)
			}

			gotReasons := make(map[string]string, len(result.Skips))
			for _, skip := range result.Skips {
				gotReasons[strconv.Itoa(skip.Number)] = string(skip.Reason)
			}
			if fmt.Sprint(gotReasons) != fmt.Sprint(expected.Reasons) {
				t.Fatalf("reasons = %v, want %v", gotReasons, expected.Reasons)
			}

			// A candidate with neither a dispatch nor a reason is a failure.
			dispatched := make(map[int]bool, len(result.Dispatches))
			for _, dispatch := range result.Dispatches {
				dispatched[dispatch.Number] = true
			}
			for _, item := range snapshot.Items {
				if item.Kind != KindTask || !item.open() {
					continue
				}
				if _, hasReason := gotReasons[strconv.Itoa(item.Number)]; !hasReason && !dispatched[item.Number] {
					t.Fatalf("#%d has neither a dispatch nor a reason", item.Number)
				}
			}
		})
	}
}

func readJSON[T any](t *testing.T, path string) T {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	var value T
	if err := json.Unmarshal(raw, &value); err != nil {
		t.Fatalf("decode %s: %v", path, err)
	}
	return value
}
